            Registry<Biome> biomeRegistry = world.registryAccess().registryOrThrow(Registries.BIOME);
            Holder<Biome> biomeHack = biomeRegistry.getHolder(ResourceKey.create(Registries.BIOME, biomeRegistry.getKey(biome)))
